-- Schema authority for the capital corpus tables in schema `capital`.
-- Generated once by ETL/archive/schema/consolidate/load_into_postgres.py from the
-- SQLite DDL on 2026-11-05; edited by migration from here on, not regenerated.
-- Applied by capital_app, whose search_path is `capital, public`.
CREATE TABLE "companies" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "canonical_name" TEXT NOT NULL,
  "raw_name" TEXT,
  "country" TEXT,
  "city" TEXT,
  "postal_code" TEXT,
  "website" TEXT,
  "entity_type" TEXT,
  "sector_inferred" TEXT,
  "pic" TEXT UNIQUE,
  "dealroom_id" TEXT,
  "crunchbase_url" TEXT,
  "linkedin_url" TEXT,
  "match_confidence" TEXT,
  "match_method" TEXT,
  "step_flagged" BIGINT DEFAULT 0,
  "notes" TEXT,
  "created_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS'),
  "sector_inferred_updated_at" TEXT,
  "entity_type_updated_at" TEXT,
  "company_group" TEXT,
  "sector_rule" TEXT,
  "parent_group" TEXT,
  "sector_top" TEXT,
  "subsector" TEXT,
  "sector_taxonomy_method" TEXT,
  "sector_taxonomy_updated_at" TEXT
);

CREATE TABLE "signals_sources" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "key" TEXT NOT NULL UNIQUE,
  "name" TEXT NOT NULL,
  "tier" TEXT NOT NULL CHECK (tier IN ('funder_press', 'trade_press', 'general_news')),
  "country" TEXT,
  "language" TEXT NOT NULL,
  "kind" TEXT,
  "feed_url" TEXT,
  "topics" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE "signals_articles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "source_id" BIGINT NOT NULL,
  "url" TEXT NOT NULL UNIQUE,
  "title" TEXT NOT NULL,
  "published_at" TEXT,
  "fetched_at" TEXT NOT NULL DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS'),
  "language" TEXT,
  "raw_text" TEXT NOT NULL,
  "full_text_fetched" BIGINT NOT NULL DEFAULT 0,
  "resolved_url" TEXT,
  "is_relevant" BIGINT,
  "relevance_reason" TEXT,
  "entities_extracted_at" TEXT,
  "signals_extracted_at" TEXT
);

CREATE TABLE "signals_article_chunks" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "article_id" BIGINT NOT NULL,
  "chunk_index" BIGINT NOT NULL,
  "chunk_text" TEXT NOT NULL,
  "char_start" BIGINT,
  "char_end" BIGINT,
  UNIQUE (article_id, chunk_index)
);

CREATE TABLE "classify_audit" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" BIGINT,
  "changed_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS'),
  "field" TEXT NOT NULL,
  "old_value" TEXT,
  "new_value" TEXT,
  "run_id" TEXT
);

CREATE TABLE "company_sector_labels" (
  "name_key" TEXT PRIMARY KEY,
  "sector_top" TEXT,
  "subsector" TEXT,
  "method" TEXT,
  "labelled_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE "company_sector_llm" (
  "company_id" BIGINT PRIMARY KEY,
  "sector" TEXT NOT NULL,
  "model" TEXT NOT NULL,
  "run_id" TEXT,
  "created_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE "corpus_run_marks" (
  "step" TEXT PRIMARY KEY,
  "run_id" TEXT NOT NULL,
  "runner" TEXT,
  "opened_at" TEXT NOT NULL,
  "closed_at" TEXT,
  "outcome" TEXT,
  "detail" TEXT
);

CREATE TABLE "private_funding_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" BIGINT,
  "event_date" TEXT,
  "round_type" TEXT,
  "amount_eur" DOUBLE PRECISION,
  "lead_investor" TEXT,
  "all_investors" TEXT,
  "investor_geography" TEXT,
  "source" TEXT,
  "source_url" TEXT,
  "confidence" TEXT,
  "notes" TEXT
);

CREATE TABLE "public_equity_stakes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" BIGINT NOT NULL,
  "holder" TEXT NOT NULL,
  "holder_type" TEXT NOT NULL CHECK (holder_type IN ( 'eu_instrument','ndb','state_vc','regional_agency', 'sovereign_fund','other')),
  "stake_pct_min" DOUBLE PRECISION,
  "stake_pct_max" DOUBLE PRECISION,
  "ticket_eur" DOUBLE PRECISION,
  "as_of" TEXT,
  "first_seen" TEXT,
  "exited" BIGINT NOT NULL DEFAULT 0,
  "source" TEXT NOT NULL,
  "raw_source_url" TEXT,
  "disclosure_level" TEXT NOT NULL CHECK (disclosure_level IN ( 'name_only','pct_range','pct_exact','amount')),
  "created_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS'),
  "via_fund" TEXT,
  UNIQUE (company_id, holder, source, as_of)
);

CREATE TABLE "public_funding_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" BIGINT,
  "source" TEXT NOT NULL,
  "role" TEXT,
  "project_number" TEXT,
  "project_acronym" TEXT,
  "project_title" TEXT,
  "project_summary" TEXT,
  "call_id" TEXT,
  "call_deadline" TEXT,
  "project_started" TEXT,
  "project_ended" TEXT,
  "grant_amount_eur" DOUBLE PRECISION,
  "equity_amount_eur" DOUBLE PRECISION,
  "total_project_cost_eur" DOUBLE PRECISION,
  "sector_tags_raw" TEXT,
  "woman_leadership" BIGINT,
  "raw_source_url" TEXT,
  "debt_amount_eur" DOUBLE PRECISION,
  "coordinator_only" BIGINT,
  "grant_amount_basis" TEXT,
  "ipcei_linked" BIGINT DEFAULT 0,
  "eif_lp_backed" BIGINT DEFAULT 0,
  "deployment_country" TEXT,
  "satr_tm_id" TEXT,
  "aid_instrument" TEXT,
  "aid_objective" TEXT,
  "granting_authority" TEXT,
  "granting_authority_country" TEXT,
  "entrusted_entity" TEXT,
  "financial_intermediaries" TEXT,
  "ndb_distributor" TEXT,
  "instrument_class" TEXT,
  "is_duplicate" BIGINT NOT NULL DEFAULT 0,
  "dup_reason" TEXT,
  "programme_ref" TEXT,
  "programme_name" TEXT
);

CREATE TABLE "satr_staging" (
  "tm_id" TEXT PRIMARY KEY,
  "country" TEXT,
  "aid_measure_title" TEXT,
  "sa_number" TEXT,
  "national_id" TEXT,
  "beneficiary_name" TEXT,
  "beneficiary_type" TEXT,
  "region" TEXT,
  "sector_nace" TEXT,
  "aid_instrument_text" TEXT,
  "objectives_text" TEXT,
  "nominal_amount_raw" TEXT,
  "aid_element_raw" TEXT,
  "date_granted" TEXT,
  "granting_authority" TEXT,
  "entrusted_entity" TEXT,
  "financial_intermediaries" TEXT,
  "published_date" TEXT,
  "beneficiary_ms" TEXT,
  "third_country" TEXT,
  "granting_country_iso2" TEXT,
  "beneficiary_country_iso2" TEXT,
  "amount_eur" DOUBLE PRECISION,
  "amount_basis" TEXT,
  "grant_year" BIGINT,
  "source_filter" TEXT,
  "company_id" BIGINT,
  "apply_status" TEXT,
  "apply_notes" TEXT
);

CREATE TABLE "schema_migrations" (
  "id" TEXT PRIMARY KEY,
  "applied_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE "signals_article_entities" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "article_id" BIGINT NOT NULL,
  "entity_type" TEXT NOT NULL CHECK (entity_type IN ('company', 'investor', 'person', 'program')),
  "mention_text" TEXT NOT NULL,
  "company_id" BIGINT,
  "match_method" TEXT,
  "match_confidence" DOUBLE PRECISION
);

CREATE TABLE "signals_article_instrument_links" (
  "article_id" BIGINT NOT NULL,
  "instrument_id" TEXT NOT NULL,
  "mention_text" TEXT,
  "match_method" TEXT NOT NULL,
  "created_at" TEXT DEFAULT to_char(timezone('UTC', now()), 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (article_id, instrument_id, match_method)
);

CREATE TABLE "signals_article_signals" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "article_id" BIGINT NOT NULL,
  "signal_type" TEXT NOT NULL CHECK (signal_type IN ( 'funding_award', 'funding_pipeline_signal', 'programme_policy_change', 'stakeholder_appointment', 'partnership_collaboration', 'regulatory_development' )),
  "confidence" DOUBLE PRECISION NOT NULL,
  "summary" TEXT NOT NULL,
  "anticipated_impact" TEXT
);

CREATE TABLE "signals_chunk_embeddings" (
  "chunk_id" BIGINT PRIMARY KEY,
  "embedding" public.vector(384) NOT NULL
);

CREATE TABLE "signals_embedding_meta" (
  "id" BIGINT PRIMARY KEY CHECK (id = 1),
  "model" TEXT NOT NULL,
  "dim" BIGINT NOT NULL
);

